// Where a client can see a property: the agency's own page for it when it
// has one, otherwise Elliot's property page with the photos (/p/<id> on the
// dashboard; photos added in Listings or imported from Google Drive). A
// Google Drive / Dropbox folder isn't a property page, so it gets ours.
const DASHBOARD_URL = 'https://app.getelliot.eu'; // change if the dashboard moves to its own domain
function propertyLink(id, url) {
  const own = String(url || '').trim();
  if (/^https?:\/\//i.test(own) && !/drive\.google\.com|dropbox\.com/i.test(own)) return own;
  return id ? `${DASHBOARD_URL}/p/${id}` : null;
}

// 0037: what kind of booking this was, and the Google Meet link for calls.
const safe = (name) => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const req = safe('When Executed by Another Workflow');
const event = safe('HTTP Request');
let details = {};
try { details = JSON.parse(req.details || '{}') || {}; } catch (e) { details = {}; }

// Normalize output for the Main Agent's tool_result formatting.
const appt = $input.first().json;
const info = $('Load Tenant + Contact Info').first().json;
return [{
  json: {
    success: true,
    appointment_id: appt.id,
    starts_at: appt.starts_at,
    ends_at: appt.ends_at,
    status: appt.status,
    listing_title: appt.listing_id ? info.listing_title || null : null,
    listing_address: appt.listing_id ? info.listing_address || null : null,
    listing_link: appt.listing_id ? propertyLink(appt.listing_id, info.listing_url) : null,
    // 0037: calls with the Elliot team
    kind: String(req.kind || '') === 'consultation' ? 'consultation' : 'viewing',
    meet_link: event.hangoutLink || null,
    call_label: details.call_type === 'demo' ? '30-minute live demo' : '15-minute intro call',
    // 0042: who will show the client round
    agent_name: (() => { try { return $('Pick Calendar').first().json.agent_name || null; } catch (e) { return null; } })(),
  }
}];

// Where a client can see a property: the agency's own page for it when it
// has one, otherwise Elliot's property page with the photos (/p/<id> on the
// dashboard; photos added in Listings or imported from Google Drive). A
// Google Drive / Dropbox folder isn't a property page, so it gets ours.
const DASHBOARD_URL = 'https://app.getelliot.eu'; // change if the dashboard moves to its own domain
function propertyLink(id, url) {
  const own = String(url || '').trim();
  if (/^https?:\/\//i.test(own) && !/drive\.google\.com|dropbox\.com/i.test(own)) return own;
  return id ? `${DASHBOARD_URL}/p/${id}` : null;
}

// The client's confirmation email (English, then Polish), sent by workflow
// 39 from the agency's name and Elliot address (0039), replies to the agency. Times are in the agency's time zone.
// 0042: with the agent who actually takes the viewing.
const info = { ...$('Load Tenant + Contact Info').first().json, ...(() => { try { return $('Pick Calendar').first().json || {}; } catch (e) { return {}; } })() };
const booked = $input.first().json;
const req = $('When Executed by Another Workflow').first().json;
const tz = info.timezone || 'Europe/Warsaw';
const start = new Date(req.starts_at);
const end = new Date(req.ends_at);
const when = (locale) =>
  `${start.toLocaleDateString(locale, { timeZone: tz, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}, ` +
  `${start.toLocaleTimeString(locale, { timeZone: tz, hour: '2-digit', minute: '2-digit' })}–` +
  `${end.toLocaleTimeString(locale, { timeZone: tz, hour: '2-digit', minute: '2-digit' })}`;
const agency = info.tenant_name || 'our office';
const first = String(info.contact_name || '').trim().split(/\s+/)[0] || '';
const link = booked.listing_link;
const facts = [
  info.listing_price != null ? `${Number(info.listing_price).toLocaleString('pl-PL')} ${info.listing_currency || 'PLN'}${info.listing_transaction_type === 'rent' ? ' / month' : ''}` : null,
  info.listing_area_m2 ? `${Number(info.listing_area_m2)} m²` : null,
  info.listing_rooms ? `${info.listing_rooms} room${info.listing_rooms === 1 ? '' : 's'}` : null,
].filter(Boolean).join(' · ');

const en = [
  `Hi${first ? ' ' + first : ''},`,
  '',
  `Your viewing with ${agency} is confirmed.`,
  '',
  `When:     ${when('en-GB')}`,
  info.listing_title ? `Property: ${info.listing_title}${info.listing_reference ? ` (ref ${info.listing_reference})` : ''}` : null,
  facts ? `          ${facts}` : null,
  info.listing_address ? `Address:  ${info.listing_address}` : null,
  info.agent_name ? `Agent:    ${info.agent_name}` : null,
  link ? `Photos and details: ${link}` : null,
  '',
  'Need to change or cancel? Just reply to this email or send us a message.',
  '',
  `See you there,`,
  agency,
].filter((l) => l !== null);

const pl = [
  `Dzień dobry${first ? ' ' + first : ''},`,
  '',
  `potwierdzamy prezentację nieruchomości z ${agency}.`,
  '',
  `Termin:   ${when('pl-PL')}`,
  info.listing_title ? `Oferta:   ${info.listing_title}${info.listing_reference ? ` (nr ${info.listing_reference})` : ''}` : null,
  info.listing_address ? `Adres:    ${info.listing_address}` : null,
  info.agent_name ? `Agent:    ${info.agent_name}` : null,
  link ? `Zdjęcia i szczegóły: ${link}` : null,
  '',
  'Jeśli chcą Państwo zmienić lub odwołać termin, wystarczy odpowiedzieć na tę wiadomość.',
  '',
  'Do zobaczenia,',
  agency,
].filter((l) => l !== null);

// 0037: getelliot.eu's own calls, and the public demo agency.
const isCall = booked.kind === 'consultation';
const isDemo = info.assistant_mode === 'demo';
if (isCall) {
  en.length = 0; pl.length = 0;
  const callEn = booked.call_label || '15-minute intro call';
  const callPl = callEn.startsWith('30') ? '30-minutowa prezentacja na żywo' : '15-minutowa rozmowa wstępna';
  en.push(`Hi${first ? ' ' + first : ''},`, '', `Your ${callEn} with Elliot is booked.`, '',
    `When:         ${when('en-GB')} (Warsaw time)`,
    booked.meet_link ? `Google Meet:  ${booked.meet_link}` : 'The Google Meet link is in the calendar invitation.', '',
    'Need another time? Just reply to this email.', '', 'Talk soon,', 'Donnovan, Elliot', 'https://getelliot.eu');
  pl.push(`Dzień dobry${first ? ' ' + first : ''},`, '', `potwierdzamy: ${callPl} z Elliot.`, '',
    `Termin:       ${when('pl-PL')} (czas warszawski)`,
    booked.meet_link ? `Google Meet:  ${booked.meet_link}` : 'Link do Google Meet jest w zaproszeniu w kalendarzu.', '',
    'Jeśli potrzebny jest inny termin, wystarczy odpowiedzieć na tę wiadomość.', '', 'Do usłyszenia,', 'Donnovan, Elliot');
}
if (isDemo) {
  en.splice(1, 0, '', 'This is a DEMO booking made on getelliot.eu. No real viewing is scheduled; this is the email your clients would get.');
  pl.splice(1, 0, '', 'To jest rezerwacja DEMO z getelliot.eu. Żadna prezentacja się nie odbędzie; tak wygląda wiadomość, którą dostają Twoi klienci.');
}
const subject = (isDemo ? '[DEMO] ' : '') + (isCall ? `Booked: Elliot ${booked.call_label || 'call'}, ` +
  `${start.toLocaleDateString('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short' })} ` +
  `${start.toLocaleTimeString('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit' })}` : '') + (isCall ? '' : `Viewing confirmed: ${start.toLocaleDateString('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short' })}, ` +
  `${start.toLocaleTimeString('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit' })}` +
  `${info.listing_title ? ' – ' + info.listing_title : ''}`);
const encodedSubject = `=?UTF-8?B?${Buffer.from(subject, 'utf8').toString('base64')}?=`;
const body = en.join('\n') + '\n\n----------------------------------------\n\n' + pl.join('\n') + '\n';
const raw =
  `To: ${info.contact_email}\r\n` +
  `Subject: ${encodedSubject}\r\n` +
  `MIME-Version: 1.0\r\n` +
  `Content-Type: text/plain; charset=UTF-8\r\n` +
  `Content-Transfer-Encoding: base64\r\n\r\n` +
  Buffer.from(body, 'utf8').toString('base64');
const encoded = Buffer.from(raw).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { to: info.contact_email, subject, body, raw_message: encoded } }];

// What goes back to Elliot (workflow 01): the booking, plus whether the
// client's confirmation email went out -- and if it failed, why, so Elliot
// tells the client instead of promising an email that isn't coming.
// A failed email never fails the booking.
const result = { ...$('Format Results').first().json };
let sentTo = null;
let error = null;
let to = null;
try {
  to = $('Build Confirmation Email').first().json.to;
  const sent = $('Send Confirmation Email').first().json;
  if (sent && sent.id && !sent.error) sentTo = to;
  else error = (sent && sent.error && (sent.error.message || sent.error.description || String(sent.error))) || 'the email was not accepted';
} catch (e) { /* no email on file: the email branch didn't run */ }
result.confirmation_sent_to = sentTo;
result.confirmation_to = to;
result.confirmation_error = sentTo ? null : error;
return [{ json: result }];

