parameters.jsCode:
// 0042: which calendar the viewing goes in. Free = nothing in Google at that
// time (plus the travel buffer) and no viewing already in the dashboard. The
// client's own agent first, then whoever has the fewest upcoming viewings.
// If Google couldn't answer for any calendar, the database rule decides, as
// before this change.
const info = $('Load Tenant + Contact Info').first().json;
const req = $('When Executed by Another Workflow').first().json;
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
const cals = (status >= 200 && status < 300 && body && body.calendars) || {};
let cands = info.candidates;
if (typeof cands === 'string') { try { cands = JSON.parse(cands); } catch (e) { cands = []; } }
cands = Array.isArray(cands) && cands.length ? cands
  : [{ calendar_id: info.google_calendar_id || 'primary', agent_id: null, agent_email: info.agent_email, agent_name: info.agent_name, mode: 'agency', is_owner: false, db_busy: false, upcoming: 0 }];
const pad = (Number(info.booking_buffer_minutes) || 0) * 60000;
const start = new Date(new Date(req.starts_at).getTime() - pad);
const end = new Date(new Date(req.ends_at).getTime() + pad);
function google(id) {
  const c = cals[id];
  if (!c) return 'unknown';
  if (c.errors && c.errors.length) return 'error';
  return (c.busy || []).some((b) => new Date(b.start) < end && new Date(b.end) > start) ? 'busy' : 'free';
}
const scored = cands.map((c) => ({ ...c, google: google(c.calendar_id) }));
let free = scored.filter((c) => !c.db_busy && c.google === 'free');
if (!free.length && scored.every((c) => c.google === 'unknown' || c.google === 'error')) free = scored.filter((c) => !c.db_busy);
free.sort((a, b) => (b.is_owner === true) - (a.is_owner === true) || (Number(a.upcoming) || 0) - (Number(b.upcoming) || 0)
  || String(a.agent_name || '').localeCompare(String(b.agent_name || '')));
const pick = free[0];
if (!pick) {
  return [{ json: { ...info, ok: false, checked: scored.map((c) => ({ calendar: c.calendar_id, google: c.google, db_busy: c.db_busy })) } }];
}
const agentEmail = pick.agent_email || null;
return [{ json: {
  ...info,
  ok: true,
  google_calendar_id: pick.calendar_id,
  calendar_mode: pick.mode || 'agency',
  agent_id: pick.agent_id || null,
  agent_email: agentEmail,
  agent_name: pick.agent_name || info.agent_name || null,
  // Invite the agent only when the event isn't already in their own calendar.
  agent_invite: agentEmail && agentEmail.toLowerCase() !== String(pick.calendar_id).toLowerCase() ? agentEmail : null,
} }];

// Nobody free at that time any more (an agent's calendar filled up since the
// times were offered). Same answer as a double booking, so Elliot offers others.
return [{ json: {
  success: false,
  error: 'slot_unavailable',
  message: 'That time is no longer available. Please choose a different slot.',
  _checked: $input.first().json.checked || [],
} }];
